-- Frammenti con parentesi in nomi_alternativi: 3 elementi in 2 specie (':(' in Pinus pinea; 'Gaggia)' e
-- 'Robinia (Acacia' in Robinia pseudoacacia, già presenti come nomi interi). Rollback: rollback_lotto6.sql
update specie set nomi_alternativi = 'Pino domestico | Pino a ombrello | Pino italico | Pino da pignoli | Italienische Steinkiefer | Pino d''Italia | Pino Daniele | Pino del dio cane | Pino marittimo' where slug = 'pinus-pinea' and specie_padre_id is null and nomi_alternativi = 'Pino domestico | Pino a ombrello | Pino italico | Pino da pignoli | Italienische Steinkiefer | Pino d''Italia | Pino Daniele | :( | Pino del dio cane | Pino marittimo';
update specie set nomi_alternativi = 'Robinia | Gaggia | Falsa Acacia | Acacia spinosa | Maruga | Robinie | Acacia | Acacia cascia | Acacia falsa | Campanello | Pseudoacacia del Turkmenistan Centro settentrionale' where slug = 'robinia-pseudoacacia' and specie_padre_id is null and nomi_alternativi = 'Robinia | Gaggia | Falsa Acacia | Acacia spinosa | Maruga | Robinie | Acacia | Acacia cascia | Acacia falsa | Campanello | Gaggia) | Pseudoacacia del Turkmenistan Centro settentrionale | Robinia (Acacia';
